UPDATE businesses SET description = 'McGregor Take Aways is a fish and chips takeaway in the Meadowridge Shopping Centre on Firgrove Way, Meadowridge. The shop is known locally for its hake and chips, served in generous portions, and is a regular stop for residents of Meadowridge and the nearby southern suburbs looking for an easy, affordable meal.

The menu is built around fried hake with golden chips, a Cape Town favourite that works just as well for a Friday night family supper as for a quick lunch. For those who want something else, there are burgers and chip rolls, which keep the menu simple and the prices friendly. Food is cooked to order and packed to take away, so customers can collect a meal on the way home and eat it hot at the table or on the beach. The relaxed, no-fuss service suits families, students and workers who want good comfort food without the cost or wait of a sit-down restaurant. Being in the local shopping centre means it is easy to pick up supper alongside the groceries. McGregor Take Aways is at Meadowridge Shopping Centre, Firgrove Way, Meadowridge, Cape Town.', description_enriched_at = datetime('now') WHERE slug = 'mcgregor-take-aways-meadowridge' AND description = 'McGregor Take Aways is a fish and chips takeaway in Meadowridge Shopping Centre, Meadowridge, known for its hake and chips.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
